mapper.select:
SELECT count(*)
FROM applications
WHERE space_id = #{spaceId} AND event_id = #{eventId}

SELECT id AS application_id, form_id, status, submitted_at
FROM applications
WHERE space_id = #{spaceId} AND event_id = #{eventId}

SELECT id AS application_id, form_id, status, submitted_at
FROM applications
WHERE id = #{applicationId} AND space_id = #{spaceId} AND event_id = #{eventId}

SELECT f.id AS field_id, f.kind, f.system_key, f.label, f.position, a.value::text AS value
FROM answers a
JOIN fields f
  ON f.space_id = a.space_id
 AND f.event_id = a.event_id
 AND f.id = a.field_id
WHERE a.space_id = #{spaceId}
  AND a.event_id = #{eventId}
  AND a.application_id = #{applicationId}
ORDER BY ${orderByClause}
